<?php
declare(strict_types=1);
require_once __DIR__.'/operator-notifications.php';
function support_notification_readiness(array $context): array {
    support_ops_admin($context);
    $account=support_ops_store(function(array &$s)use($context){support_ops_recheck($s,$context);$subscriptions=array_values(array_filter($s['subscriptions'],fn($r)=>$r['operator']===$context['operator_id']));$active=array_values(array_filter($subscriptions,fn($r)=>$r['expires']>time()&&$r['session_expires']>time()&&isset($r['session'])&&is_file(support_runtime_dir().'/sessions-operator/sess_'.$r['session'])));$p=$s['preferences'][$context['operator_id']]??[];
        return ['subscriptions'=>count($subscriptions),'active_subscriptions'=>count($active),'next_expiry'=>$active?min(array_map(fn($r)=>min($r['expires'],$r['session_expires']),$active)):null,'quiet_now'=>support_alert_quiet($p),'sms_opt_in'=>($p['sms']??false)===true];});
    $vapid=['state'=>'Unknown','ready'=>false,'public_fingerprint'=>null];try{$key=support_push_keys();$vapid=['state'=>'Healthy','ready'=>true,'public_fingerprint'=>substr(hash('sha256',$key['public']),0,16)];unset($key);}catch(Throwable $ignored){}
    $flags=[];foreach(['SUPPORT_OPERATOR_PUSH_ENABLED','SUPPORT_OPERATOR_PUSH_REAL_ENABLED','SUPPORT_OPERATOR_SMS_ENABLED','SUPPORT_OPERATOR_SMS_REAL_ENABLED','SUPPORT_CUSTOMER_PUSH_ENABLED','SUPPORT_CUSTOMER_PUSH_REAL_ENABLED','SUPPORT_NOTIFICATION_QUEUE_ENABLED','SUPPORT_SMS_REAL_DELIVERY_ENABLED','SUPPORT_RECOVERY_EMAIL_REAL_DELIVERY_ENABLED']as $name)$flags[$name]=getenv($name)==='1';
    return ['status'=>'success','checked_at'=>time(),'https'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||(int)($_SERVER['SERVER_PORT']??0)===443,'flags'=>$flags,'vapid'=>$vapid,'account'=>$account,
        'configuration'=>['curl'=>function_exists('curl_exec'),'openssl'=>function_exists('openssl_sign'),'push_contact_configured'=>preg_match('/^mailto:[^\s@]+@[^\s@]+$/D',getenv('SUPPORT_PUSH_CONTACT')?:'')===1,'sms_credentials_configured'=>preg_match('/^[a-zA-Z0-9_-]{16,256}$/D',getenv('SMSIR_API_KEY')?:'')===1,'sms_template_configured'=>preg_match('/^[1-9][0-9]{0,8}$/D',getenv('SUPPORT_OPERATOR_SMS_TEMPLATE_ID')?:'')===1,'sms_recipient_source_configured'=>(getenv('SUPPORT_OPERATOR_SMS_RECIPIENTS_FILE')?:'')!==''],
        'policy'=>['sms_delay_seconds'=>support_option_int('SUPPORT_OPERATOR_SMS_DELAY',300,0,86400),'sms_daily_budget'=>support_option_int('SUPPORT_OPERATOR_SMS_DAILY_BUDGET',10,0,100),'quiet_start'=>support_option_int('SUPPORT_OPERATOR_QUIET_START',22,0,23),'quiet_end'=>support_option_int('SUPPORT_OPERATOR_QUIET_END',8,0,23),'interactive_session_seconds'=>1800,'absolute_session_seconds'=>28800,'subscription_max_days'=>30,'vapid_jwt_seconds'=>300,'push_ttl_seconds'=>60,'push_urgency'=>'normal','apple_vapid_cadence'=>'NOT VERIFIED; current sender signs per request','worker_max_jobs'=>10,'worker_max_seconds'=>30,'per_operator_sms_daily'=>3,'push_payload'=>'generic_authorized_hint','deduplication'=>'persistent_job_key_and_shared_device_cursor','revocation'=>'account_version_session_logout_expiry_rechecked'],
        'network'=>['state'=>'Unknown','tested'=>false,'requirements'=>['browser to this HTTPS origin','server and device to selected push provider: fcm.googleapis.com / updates.push.services.mozilla.com / web.push.apple.com','server to SMS.ir HTTPS API; operator mobile network for SMS'],'national_network_delivery'=>'NOT VERIFIED; never guaranteed'],'physical_devices'=>'NOT VERIFIED'];
}
